import re, glob, os
from collections import Counter
pat = re.compile(r'^(\d{4}-\d{2}-\d{2}) \d{2}:\d{2}:\d{2} \[(ERROR|WARNING|INFO|DEBUG)\] ')
cnt = Counter()
for f in sorted(glob.glob('/app/logs/*.log')):
    date_str = os.path.basename(f).split('_')[0]
    for line in open(f):
        m = pat.match(line)
        if not m: continue
        if '2025-07-14' <= m.group(1) <= '2025-08-12':
            cnt[(m.group(1), m.group(2))] += 1
for (d,s),c in sorted(cnt.items()):
    if s=='ERROR': print(d, s, c)
EOF
